head.script:
scwin.s_onblur = function(e) {
    //alert("onblur");
    log = "onblur";
};
scwin.checkVal = function() {
    return log == 'onblur';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();

    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('s_input_0').focus()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('s_input_0').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('s_input_0').blur()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    window.log;
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 06-Mar-2018
    //End unitTest
}
